BEGIN;SET LOCAL lock_timeout='3s';REVOKE ALL ON FUNCTION public.refund_original_sale_v1(uuid,uuid,uuid,uuid,numeric,boolean,uuid,jsonb) FROM PUBLIC,anon,authenticated,service_role;DO $$DECLARE r record;BEGIN FOR r IN SELECT DISTINCT pg_get_userbyid(a.grantee) name FROM pg_proc p CROSS JOIN LATERAL aclexplode(coalesce(p.proacl,acldefault('f',p.proowner))) a WHERE p.oid='public.refund_original_sale_v1(uuid,uuid,uuid,uuid,numeric,boolean,uuid,jsonb)'::regprocedure AND a.grantee<>0 AND a.grantee<>p.proowner LOOP EXECUTE format('REVOKE ALL ON FUNCTION public.refund_original_sale_v1(uuid,uuid,uuid,uuid,numeric,boolean,uuid,jsonb) FROM %I',r.name);END LOOP;END$$;UPDATE backend_core.settlement_rollout SET enabled=false WHERE enabled;COMMIT;
